function CardProgressionObserveDialog:InitData()
    local argument   = self.controller.Argument
    local parameters = argument.parameters
    local cardId     = parameters.cardId
    local isCat      = checkNumber(parameters.isCat) == 1
    local cardSkin   = parameters.cardSkin
    self._cardId     = cardId
    self._isCat      = isCat
    self._cardSkin   = cardSkin
    
    ---@type CardProgressionControllerRole
    local env = CardProgressionUtils.GetRoleControllerEnv()
    self._controllerEnv = env
end

function CardProgressionObserveDialog:InitTouchReceive()
    ---@type CardPositionVo
    local positionVo = cardConfMgr:GetCardPosByCardId(self._cardId, self._cardSkin)
    
    ---@type CardProgressionControllerRole
    local controllerEnv      = self._controllerEnv
    ---@type UnityEngine.Transform
    local virtualCameraTrans = controllerEnv:GetCultivateCameraTrans()
    local up                 = virtualCameraTrans.up
    local forward            = virtualCameraTrans.forward
    local originLocalPos     = virtualCameraTrans.localPosition
    ---todo 猫参数 enlargeRoleCam
    local enlargeRoleCam     = positionVo.enlargeRoleCam
    
    --- enlargeRoleCam: 人物最大:人物最小;猫最大:猫最小
    local enlargeRoleCamConf = enlargeRoleCam[self._isCat and 2 or 1]
    local forwardConf        = parse_strings(enlargeRoleCamConf, ":")
    local maxForwardDistance = checkNumber(forwardConf[1])
    local minForwardDistance = checkNumber(forwardConf[2])
    
    self._curForwardDistance = minForwardDistance
    self._minForwardDistance = minForwardDistance
    self._maxForwardDistance = maxForwardDistance
    
    self._virtualCameraTrans   = virtualCameraTrans
    self._virtualCameraUp      = up
    self._virtualCameraForward = forward
    self._originLocalPos       = originLocalPos
    self._enlargeRoleCam       = enlargeRoleCam
    ---------------------------
    --- 处理单指操作
    local abs                = math.abs
    local upDownDistance     = positionVo.upDownDistance
    local upDownDistanceConf = upDownDistance[self._isCat and 2 or 1]
    local upDownConf         = parse_strings(upDownDistanceConf, ":")
    local maxUpDistance      = checkNumber(upDownConf[1])
    local minUpDistance      = checkNumber(upDownConf[2])
    self._curUpDistance      = maxUpDistance
    self._minUpDistance      = minUpDistance
    self._maxUpDistance      = maxUpDistance
    
    self.TouchReceive.onSingleFingerDrag:AddListener(function(delta)
        if self:IsTween() then
            return
        end
        local y = delta.y
        local x = delta.x
        local absX = abs(x)
        local absY = abs(y)
        if abs(absX - absY) <= 2 then
            return
        end
        ---左右滑动旋转
        if absY <= absX then
            if CardProgressionUtils.IsTween() then
                return
            end
            local direction = x < 0 and 1 or -1
            Events.Broadcast(CardProgressionConstants.EventNames.RotationRole, direction * abs(x))
            --local direction = x < 0 and 1 or -1
            --local eulerAngles = Vector3.New(0, direction * abs(x), 0)
            --root.transform:Rotate(eulerAngles)
            --Events.Broadcast(CardProgressionConstants.EventNames.RotationRole, eulerAngles)
            return
        end
        
        local offset = y / dpi
        local distance = self._curUpDistance + offset
        distance = math.max(self._minUpDistance, math.min(distance, self._maxUpDistance))
        self._curUpDistance = distance
        
        self:InitCamera(self._curForwardDistance, self._curUpDistance)

    end)
    
    

    ---------------------------
    --- 处理双指操作
    --local maxProgress    = math.abs((enlargeRoleCam.z - originLocalPos.z) / forward.z)
    --self._maxProgress = maxProgress
    --self.TouchReceive.onPinchZoom:AddListener(function(delta, isScrollWheel)
    --    if self:IsTween() then
    --        return
    --    end
    --    local offset = delta
    --    if checkNumber(isScrollWheel) == 0 then
    --        offset = offset / dpi * 2
    --    end
    --    
    --    self:FreshSliderByOffset(offset)
    --    
    --end)

    self.TouchReceive.onPinchZoom:AddListener(function(delta, isScrollWheel)
        if self:IsTween() then
            return
        end
        local offset = delta
        if checkNumber(isScrollWheel) == 0 then
            offset = offset * 10
        end
        offset = math.min(abs(offset), 0.2) * offset > 0 and -1 or 1
        self:FreshSliderByOffset(offset)

    end)

    self.Slider.value = 1

    ---------------------------
    --- 处理进度条事件
    self.Slider.onValueChanged:AddListener(function (value)
        if self.isLookAt then return end
        self._curForwardDistance = self._minForwardDistance + (1-value) * (self._maxForwardDistance - self._minForwardDistance)
        self:InitCamera(self._curForwardDistance, self._curUpDistance)
        
    end)

end

