---InitCamera
---@param forwardDistance number
function CardProgressionObserveDialog:InitCamera(forwardDistance, upDistance)
    ---@type CardProgressionControllerRole
    local controllerEnv = self._controllerEnv
    controllerEnv:FreshCameraState(CardProgressionConstants.CameraState.CultivateLookAtFace, self._isCat, forwardDistance, upDistance)
    
end

function CardProgressionObserveDialog:FreshSliderByOffset(offset)
    local distance = self._curForwardDistance + offset
    distance = math.max(self._minForwardDistance, math.min(distance, self._maxForwardDistance))
    self.Slider.value = 1 - (distance - self._minForwardDistance) / (self._maxForwardDistance - self._minForwardDistance)
    
end

function CardProgressionObserveDialog:RefreshUIShowState(isShow)
    KTool.SetActive(self.Container.gameObject, isShow)
end

function CardProgressionObserveDialog:IsTween()
    return CardProgressionUtils.IsTween()
end

